#include "command_result_mapper/reconstruction_command_result_mapper.hpp"
#include <sstream>
namespace command_result_mapper::reconstruction { namespace { std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='"'||c=='\\')o+='\\';o+=c;}return o;} template<class V>std::string list(const V&v){std::ostringstream o;o<<'[';for(size_t i=0;i<v.size();++i){if(i)o<<',';o<<"{\"code\":\""<<esc(v[i].code)<<"\",\"message\":\""<<esc(v[i].message)<<"\"}";}return o.str()+']';} std::string b(bool v){return v?"true":"false";} }
common::CommandResult toCommandResult(const ::reconstruction::ReconstructionValidationResult&r){return common::success({{"valid",b(r.valid)},{"issue_count",std::to_string(r.issues.size())},{"issues_json",list(r.issues)},{"warning_count",std::to_string(r.warnings.size())},{"warnings_json",list(r.warnings)},{"image_width",std::to_string(r.image_width)},{"image_height",std::to_string(r.image_height)},{"projector_width",std::to_string(r.projector_width)},{"projector_height",std::to_string(r.projector_height)},{"left_valid_count",std::to_string(r.left_valid_count)},{"right_valid_count",std::to_string(r.right_valid_count)},{"valid_correspondence_count",std::to_string(r.diagnostics.valid_correspondence_count)},{"reconstructable_point_count",std::to_string(r.reconstructable_point_count)}});}
common::CommandResult toCommandResult(const ::reconstruction::ReconstructionResult&r){if(!r.ok)return common::failure(r.error?r.error->code:"internal_error",r.error?r.error->message:"reconstruction failed");return common::success({{"output_file",r.output_file.string()},{"point_count",std::to_string(r.point_count)},{"valid_correspondence_count",std::to_string(r.diagnostics.valid_correspondence_count)},{"warning_count",std::to_string(r.warnings.size())},{"warnings_json",list(r.warnings)}});}
}
